/**
 * Check if an enchant is valid for a given slot based on slot restrictions
 * @param {string} enchantName - The enchant name
 * @param {number} effectId - The effect ID
 * @param {string} slot - The gear slot
 * @returns {boolean} True if the enchant is valid for this slot
 */
function isEnchantValidForSlot(enchantName, effectId, slot) {
    const slotRestrictions = EFFECT_ID_SLOT_MAP[effectId];
    if (!slotRestrictions) {
        return true; // No restrictions for this effect ID
    }

    const restriction = slotRestrictions[enchantName];
    if (!restriction) {
        return true; // No restriction for this specific enchant
    }

    const allowedSlots = ENCHANT_SLOT_RESTRICTIONS[restriction];
    return allowedSlots && allowedSlots.includes(slot);
}

/**
 * Find enchant index in the enchant database by effect ID
 * @param {string} slot - The gear slot (e.g., 'wrist', 'hands')
 * @param {number} effectId - The effect ID from armory
 * @param {Object} enchantDatabase - The enchant database
 * @returns {number} The enchant index or 0 (None) if not found
 */
export function findEnchantIndexByEffectId(slot, effectId, enchantDatabase) {
    const enchants = enchantDatabase[slot];
    if (!enchants) return 0;

    // First, try to find enchant by matching effect_id directly in the database
    // This handles shared effect IDs by checking slot validity
    let index = enchants.findIndex(e => {
        if (e.effect_id !== effectId) return false;
        // Check if this enchant is valid for the current slot
        return isEnchantValidForSlot(e.name, effectId, slot);
    });

    if (index !== -1) {
        console.log(`✓ Found enchant by effect_id: ${enchants[index].name} at index ${index} for slot: ${slot}`);
        return index;
    }

    // Fallback: try name-based matching using the effect ID map
    const enchantName = getEnchantNameByEffectId(effectId);
    if (!enchantName) {
        console.warn(`Unknown enchant effect ID: ${effectId} for slot: ${slot}`);
        return 0;
    }

    // Try exact match by name
    index = enchants.findIndex(e => {
        if (e.name !== enchantName) return false;
        return isEnchantValidForSlot(e.name, effectId, slot);
    });

    if (index !== -1) {
        console.log(`✓ Found enchant by name: ${enchantName} at index ${index} for slot: ${slot}`);
        return index;
    }

    // Try partial match (enchant name might differ slightly)
    index = enchants.findIndex(e => {
        const nameLower = e.name.toLowerCase();
        const enchantLower = enchantName.toLowerCase();
        // Remove common prefix for matching
        const cleanName = nameLower.replace(/^enchant (bracer|gloves|boots|weapon|shield|cloak|chest|legs) - /, '');
        const cleanEnchant = enchantLower.replace(/^enchant (bracer|gloves|boots|weapon|shield|cloak|chest|legs) - /, '');
        const matches = cleanName.includes(cleanEnchant) || cleanEnchant.includes(cleanName);

        if (!matches) return false;

        return isEnchantValidForSlot(e.name, effectId, slot);
    });

    if (index !== -1) {
        console.log(`✓ Found partial match: ${enchantName} at index ${index} for slot: ${slot}`);
        return index;
    }

    console.warn(`✗ Enchant not found in database or not valid for slot: ${enchantName} (effect ID: ${effectId}) for slot: ${slot}`);
    return 0;
}
